import React, { useState } from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import Register from './components/member/Register';
import Login from './components/member/Login';
import SetPassword from './components/member/SetPassword';
import ResetPassword from './components/member/ResetPassword';
import SetNewPassword from './components/member/SetNewPassword';
import Dashboard from './components/member/Dashboard';
import styles from './App.module.css';
import ProtectedRoute from './components/ProtectedRoute';


const countries = {
  "United States": "USD",
  "Kenya": "KES",
  "India": "INR",
  "Nigeria": "NGN",
  "Ghana": "GHS",
  "Uganda": "UGX",
  "United Kingdom": "GBP",
  "Canada": "CAD",
  "Australia": "AUD",
  "South Africa": "ZAR",
  "Germany": "EUR",
  "France": "EUR",
  "Japan": "JPY",
  "China": "CNY",
  "Brazil": "BRL"
};

const exchangeRates = {
  "USD": { "KES": 129.5, "INR": 83.3, "NGN": 1500, "GHS": 15.5, "UGX": 3700 },
  "KES": { "USD": 0.0077, "INR": 0.64, "NGN": 11.6, "GHS": 0.12, "UGX": 28.6 },
};

function Home() {
  const [fromCountry, setFromCountry] = useState("");
  const [toCountry, setToCountry] = useState("");
  const [fromValue, setFromValue] = useState("");
  const [toValue, setToValue] = useState("");
  const [showInitialCountries, setShowInitialCountries] = useState(true);
  const [showToButton, setShowToButton] = useState(false);

  const handleFromChange = (e) => {
    const newFromCountry = e.target.value;
    setFromCountry(newFromCountry);
    if (toCountry && newFromCountry && fromValue && isValidAmount(fromValue)) {
      setShowInitialCountries(false);
      setShowToButton(true);
      calculateToValue(newFromCountry, toCountry, fromValue);
    }
  };

  const handleToChange = (e) => {
    const newToCountry = e.target.value;
    setToCountry(newToCountry);
    if (fromCountry && newToCountry && fromValue && isValidAmount(fromValue)) {
      setShowInitialCountries(false);
      setShowToButton(true);
      calculateToValue(fromCountry, newToCountry, fromValue);
    }
  };

  const handleFromValueChange = (e) => {
    const value = e.target.value;
    if (isValidAmount(value)) {
      setFromValue(value);
      if (fromCountry && toCountry && value) {
        setShowInitialCountries(false);
        setShowToButton(true);
        calculateToValue(fromCountry, toCountry, value);
      }
    } else {
      setFromValue("");
      setShowToButton(false);
      setToValue("");
    }
  };

  const isValidAmount = (value) => {
    const numValue = parseFloat(value);
    return !isNaN(numValue) && numValue >= 1 && numValue <= 1000000;
  };

  const calculateToValue = (from, to, amount) => {
    if (!amount || !isValidAmount(amount) || !from || !to) {
      setToValue("");
      return;
    }
    const fromCurrency = countries[from];
    const toCurrency = countries[to];
    const rate = exchangeRates[fromCurrency]?.[toCurrency] || 1;
    const result = (amount * rate).toFixed(2);
    setToValue(result);
  };

  return (
    <div className={styles.container}>
      <div className={styles.logo}>
        <img src="/images/payzarc.png" alt="Payzarc" className={styles.appLogo} />
      </div>
      <p className={styles.slogan}>Your trusted cross-border financial partner at a go.</p>
      <div className={styles.navLinkss}>
        <span>All</span>
        <span>International Transfer</span>
        <span>Merchants/Ag</span>
      </div>
      <div className={styles.content}>
        <button className={`${styles.authButton} ${styles.google}`} onClick={() => { }}>
          <img src="https://www.google.com/favicon.ico" alt="Google" className={styles.icon} />
          Sign up with Google
        </button>
        <button className={`${styles.authButton} ${styles.apple}`} onClick={() => { }}>
          <img src="https://www.apple.com/favicon.ico" alt="Apple" className={styles.icon} />
          Sign up with Apple
        </button>
        <div className={styles.or}>--------OR--------</div>
        <button className={`${styles.authButton} ${styles.create}`} onClick={() => window.location.href = 'components/member/register'}>
          Create account
        </button>
        <div className={styles.or}>Have account, send money to</div>
        <div className={styles.countryAmt}>
          <div className={styles.countryRow}>
            <select className={styles.dropdown} value={fromCountry} onChange={handleFromChange}>
              <option value="">From</option>
              {Object.keys(countries).map(country => (
                <option key={country} value={country}>{`${country} (${countries[country]})`}</option>
              ))}
            </select>
            {showToButton ? (
              <button className={`${styles.dropdown} ${styles.toButton}`}>{`${toCountry} (${countries[toCountry]})`}</button>
            ) : (
              <select className={styles.dropdown} value={toCountry} onChange={handleToChange}>
                <option value="">To</option>
                {Object.keys(countries).map(country => (
                  <option key={country} value={country}>{`${country} (${countries[country]})`}</option>
                ))}
              </select>
            )}
          </div>
          <div className={styles.amountRow}>
            <input
              type="number"
              className={styles.amountInput}
              placeholder="Amount"
              value={fromValue}
              onChange={handleFromValueChange}
              min="1"
              max="100000"
            />
          </div>
          {toValue && <div className={styles.toValueRow}> {toValue} {countries[toCountry]}</div>}
          {(fromCountry && toCountry && fromValue && isValidAmount(fromValue)) && (
            <button className={styles.sendButton} onClick={() => window.location.href = 'components/member/login'}>{`Send to ${toCountry}`}</button>
          )}
        </div>
        {showInitialCountries && (
          <div className={styles.countryButtons}>
            <button className={styles.countryBtn} onClick={() => window.location.href = 'components/member/login'}>India</button>
            <button className={styles.countryBtn} onClick={() => window.location.href = 'components/member/login'}>Nigeria</button>
            <button className={styles.countryBtn} onClick={() => window.location.href = 'components/member/login'}>Ghana</button>
            <button className={styles.countryBtn} onClick={() => window.location.href = 'components/member/login'}>Uganda</button>
          </div>
        )}
        <div className={styles.contact}>
          <a href="mailto:info.e@payzarc.com">info.e@payzarc.com</a>
          <p>+1 (713) 822-8593</p>
          <p>Kew Gardens Dr Houston Tx, USA</p>
        </div>
      </div>
    </div>
  );
}

function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="components/member/register" element={<Register onBack={() => window.location.href = '/'} />} />
        <Route path="components/member/login" element={<Login onBack={() => window.location.href = '/'} />} />
        <Route path="components/member/set-password" element={<SetPassword onBack={() => window.location.href = '/'} />} />
        <Route path="components/member/reset-password" element={<ResetPassword onBack={() => window.location.href = '/'} />} />
        <Route path="components/member/set-new-password" element={<SetNewPassword onBack={() => window.location.href = '/'} />} />
        {/* <Route path="components/member/dashboard" element={<Dashboard onBack={() => window.location.href = '/'} />} />*/}


        {/* ← PROTECTED ROUTE */}
        <Route
          path="components/member/dashboard"
          element={
            <ProtectedRoute>
              <Dashboard />
            </ProtectedRoute>
          }
        />

        {/* Optional: redirect any unknown route to home or login */}
        <Route path="*" element={<Home />} />
      </Routes>
    </BrowserRouter>
  );
}

export default App;


